package com.bank.jvm.flags;

import java.util.List;
import java.util.logging.Logger;

public class JvmFlagInspector {
    private static final Logger log = Logger.getLogger(JvmFlagInspector.class.getName());

    public static void main(String[] args) {
        log.info("Bank: National Bank of India — JVM flag inspector");

        RuntimeConfigReporter reporter = new RuntimeConfigReporter();
        reporter.reportHeap();
        reporter.reportCollectors();
        reporter.reportInputArgs();

        BaselineFlags baseline = new BaselineFlags();
        log.info("Recommended baseline flags and WHY:");
        for (String line : baseline.explain()) {
            log.info(() -> "  " + line);
        }
        log.info("Confirm effective values with: java -XX:+PrintFlagsFinal -version");
    }
}

// ─── Would be in BaselineFlags.java in a real project ───
class BaselineFlags {
    List<String> explain() {
        return List.of(
            "-XX:MaxRAMPercentage=75.0  -> heap = 75% of container limit (leaves non-heap room)",
            "-XX:+UseG1GC               -> balanced default collector",
            "-XX:MaxGCPauseMillis=200   -> soft pause target for G1",
            "-XX:MaxMetaspaceSize=256m  -> cap class-metadata native memory, fail fast if leaked",
            "-XX:+HeapDumpOnOutOfMemoryError -> auto-capture evidence on OOM",
            "-XX:+ExitOnOutOfMemoryError     -> terminate so k8s restarts cleanly",
            "-Xlog:gc*:file=gc.log:time,tags -> never tune GC blind",
            "-XX:+PrintFlagsFinal (ad hoc)   -> audit what the JVM actually decided"
        );
    }
}
