package com.bank.jvm.flags;

import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.lang.management.RuntimeMXBean;
import java.util.logging.Logger;

class RuntimeConfigReporter {
    private static final Logger log = Logger.getLogger(RuntimeConfigReporter.class.getName());

    void reportHeap() {
        long maxMb = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getMax() / (1024 * 1024);
        log.info(() -> "Effective max heap (-Xmx/MaxRAMPercentage) = " + maxMb + "MB");
    }

    void reportCollectors() {
        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            log.info(() -> "Active collector: " + gc.getName());
        }
    }

    void reportInputArgs() {
        RuntimeMXBean runtime = ManagementFactory.getRuntimeMXBean();
        log.info(() -> "JVM input args: " + runtime.getInputArguments());
    }
}
